def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(n, int) or n < 0:
        raise ValueError("The degree n must be a non-negative integer.")
    if not isinstance(coeffs, list) or len(coeffs) != n + 1:
        raise ValueError("Coeffs must be a list of integers with length n+1.")
    if not all(isinstance(coeff, int) for coeff in coeffs):
        raise ValueError("All coefficients must be integers.")

    terms = []
    for degree, coeff in enumerate(coeffs):
        if coeff == 0:
            continue

        abs_coeff = abs(coeff)
        sign = '+' if coeff > 0 else '-'
        if len(terms) == 0:
            sign = '' if coeff > 0 else '-'

        if degree == 0:
            term = f"{abs_coeff}"
        elif degree == 1:
            term = f"{abs_coeff}x" if abs_coeff != 1 else "x"
        else:
            term = f"{abs_coeff}x^{degree}" if abs_coeff != 1 else f"x^{degree}"

        terms.append(f"{sign}{term}")

    return ''.join(terms)

